"use client";

import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import {
  useLoginForm,
  type LoginCredentials,
  type LoginSubmitResult,
} from "@/hooks/use-login-form";

export type LoginField = {
  name: string;
  label?: string;
  type?: string;
  placeholder?: string;
  autoComplete?: string;
};

export type LoginFormProps = {
  /**
   * Caller-supplied submit. Resolve to succeed; return `{ error }` /
   * `{ rateLimited: true }`, or throw, to fail. No transport assumed.
   */
  onSubmit: (credentials: LoginCredentials) => Promise<LoginSubmitResult>;
  /** Fields to render. Defaults to a single password field. */
  fields?: LoginField[];
  title?: string;
  submitLabel?: string;
  loadingLabel?: string;
  className?: string;
};

const DEFAULT_FIELDS: LoginField[] = [
  {
    name: "password",
    label: "password",
    type: "password",
    placeholder: "password",
    autoComplete: "current-password",
  },
];

/**
 * Styled login view over the headless useLoginForm hook. Renders one or more
 * fields, an error line (generic or rate-limited), and a submit button that
 * reflects the loading state. Plain <form> — no router, no fetch.
 */
export function LoginForm({
  onSubmit,
  fields = DEFAULT_FIELDS,
  title = "log in",
  submitLabel = "log in",
  loadingLabel = "signing in...",
  className,
}: LoginFormProps) {
  const form = useLoginForm({
    onSubmit,
    fields: fields.map((f) => f.name),
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        void form.submit();
      }}
      className={cn("flex w-full max-w-sm flex-col gap-3", className)}
    >
      {title && (
        <h1 className="text-center text-sm lowercase text-white">{title}</h1>
      )}

      {fields.map((field, i) => (
        <Input
          key={field.name}
          type={field.type ?? "text"}
          aria-label={field.label ?? field.name}
          placeholder={field.placeholder ?? field.label ?? field.name}
          autoComplete={field.autoComplete}
          autoFocus={i === 0}
          value={form.values[field.name] ?? ""}
          disabled={form.loading}
          onChange={(e) => form.setValue(field.name, e.target.value)}
          onKeyDown={form.onKeyDown}
          className="w-full"
        />
      ))}

      {form.error && (
        <p
          className={cn(
            "text-center text-xs lowercase",
            form.rateLimited ? "text-amber-400" : "text-red-400",
          )}
        >
          {form.error}
        </p>
      )}

      <button
        type="submit"
        disabled={form.loading}
        className={cn(
          "w-full border border-white/20 bg-white/90 px-4 py-1.5 text-sm",
          "lowercase text-black transition-colors hover:bg-white",
          "disabled:opacity-60",
        )}
      >
        {form.loading ? loadingLabel : submitLabel}
      </button>
    </form>
  );
}

"use client";

import { useState } from "react";

export type LoginCredentials = Record<string, string>;

export type LoginSubmitResult = {
  /** Set true to surface the rate-limited state instead of a generic error. */
  rateLimited?: boolean;
  /** Optional error message; presence marks the attempt as failed. */
  error?: string;
} | void;

export type UseLoginFormOptions = {
  /**
   * Caller-supplied submit. Resolve to signal success; return
   * `{ error }` / `{ rateLimited: true }`, or throw, to signal failure.
   * No transport is assumed — wire it to fetch, an action, anything.
   */
  onSubmit: (credentials: LoginCredentials) => Promise<LoginSubmitResult>;
  /** Field names the form collects. Defaults to a single "password". */
  fields?: string[];
  /** Message shown when onSubmit throws. */
  networkError?: string;
  /** Message shown when a result/throw flags rate limiting. */
  rateLimitedError?: string;
  /** Fallback message for a generic failed attempt. */
  defaultError?: string;
};

export type UseLoginFormReturn = {
  values: LoginCredentials;
  setValue: (name: string, value: string) => void;
  loading: boolean;
  error: string;
  rateLimited: boolean;
  /** Run the submit flow. */
  submit: () => Promise<void>;
  /** Wire to inputs for Enter-to-submit. */
  onKeyDown: (e: React.KeyboardEvent) => void;
};

/**
 * Headless login state machine: holds field values, loading + error +
 * rateLimited flags, an Enter-to-submit handler, and a submit runner that
 * delegates to an injected onSubmit. Framework- and transport-agnostic.
 */
export function useLoginForm({
  onSubmit,
  fields = ["password"],
  networkError = "network error. try again.",
  rateLimitedError = "too many attempts. try again later.",
  defaultError = "incorrect credentials.",
}: UseLoginFormOptions): UseLoginFormReturn {
  const [values, setValues] = useState<LoginCredentials>(() =>
    Object.fromEntries(fields.map((f) => [f, ""])),
  );
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [rateLimited, setRateLimited] = useState(false);

  const setValue = (name: string, value: string) =>
    setValues((prev) => ({ ...prev, [name]: value }));

  const submit = async () => {
    if (loading) return;
    setError("");
    setRateLimited(false);
    setLoading(true);
    try {
      const result = await onSubmit(values);
      if (result?.rateLimited) {
        setRateLimited(true);
        setError(result.error ?? rateLimitedError);
      } else if (result?.error) {
        setError(result.error);
      }
    } catch (e) {
      const limited =
        typeof e === "object" && e !== null && "rateLimited" in e
          ? Boolean((e as { rateLimited?: unknown }).rateLimited)
          : false;
      if (limited) {
        setRateLimited(true);
        setError(rateLimitedError);
      } else {
        setError(e instanceof Error && e.message ? e.message : networkError);
      }
    } finally {
      setLoading(false);
    }
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault();
      void submit();
    }
  };

  return { values, setValue, loading, error, rateLimited, submit, onKeyDown };
}
